:28;i:1;i:35;i:2;i:53;}s:10:\"popularity\";d:107.4648;s:12:\"release_date\";s:10:\"2026-03-14\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:6.81;s:10:\"vote_count\";i:153;}i:10;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/qcIKxhqGMIj8uujsSoSMZWr8QqU.jpg\";s:2:\"id\";i:1122573;s:5:\"title\";s:11:\"In the Grey\";s:14:\"original_title\";s:11:\"In the Grey\";s:8:\"overview\";s:116:\"Film, iki çıkarma uzmanının yaşlı bir kadın müzakerecinin kaçış rotasını belirlemesi etrafında döner.\";s:11:\"poster_path\";s:32:\"/dQgIcW6Th08kMRf2HBoYWoFE6OD.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"en\";s:9:\"genre_ids\";a:2:{i:0;i:28;i:1;i:53;}s:10:\"popularity\";d:200.2969;s:12:\"release_date\";s:10:\"2026-05-13\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:6.6;s:10:\"vote_count\";i:197;}i:11;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/n7WeIugzFXXkkCO6ps3GClKvn7V.jpg\";s:2:\"id\";i:1430077;s:5:\"title\";s:5:\"Hokum\";s:14:\"original_title\";s:5:\"Hokum\";s:8:\"overview\";s:215:\"Film, anne babasının küllerini serpmek için irlanda kırsalındaki tenha bir otele giden yazar Ohm Bauman\'ın, orada dinlediği hikayelerin zihnini ele geçirmeye başlamasıyla başından geçenleri anlatıyor.\";s:11:\"poster_path\";s:32:\"/4bR3qWlf4PhSSmiXmYEuI40j9vd.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"en\";s:9:\"genre_ids\";a:1:{i:0;i:27;}s:10:\"popularity\";d:147.5482;s:12:\"release_date\";s:10:\"2026-04-29\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:6.708;s:10:\"vote_count\";i:204;}i:12;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/2I1OFQJ0L9T0dpU6FobKFWV2PxX.jpg\";s:2:\"id\";i:687163;s:5:\"title\";s:17:\"Kurtuluş Projesi\";s:14:\"original_title\";s:17:\"Project Hail Mary\";s:8:\"overview\";s:549:\"Fen bilgisi öğretmeni Ryland Grace, evinden ışık yılları uzakta bir uzay gemisinde uyanır, kim olduğuna ya da oraya nasıl geldiğine dair hiçbir şey hatırlamaz. Hafızası yavaş yavaş yerine gelirken görevini de çözmeye başlar: Güneşin sönmesine neden olan gizemli maddenin sırrını çözmek. Dünyadaki her şeyi yok olmaktan kurtarmak için tüm bilimsel bilgisine ve sıra dışı fikirlerine başvurmak zorundadır. Ancak beklenmedik bir dostluk, bu görevi tek başına yapmak zorunda kalmayacağı anlamına gelecektir.\";s:11:\"poster_path\";s:32:\"/suFNqtGOi0BsBI3uJPKkDXCwgVI.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"en\";s:9:\"genre_ids\";a:2:{i:0;i:878;i:1;i:12;}s:10:\"popularity\";d:188.8313;s:12:\"release_date\";s:10:\"2026-03-15\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:8.674;s:10:\"vote_count\";i:4916;}i:13;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/9Z2uDYXqJrlmePznQQJhL6d92Rq.jpg\";s:2:\"id\";i:1226863;s:5:\"title\";s:26:\"Süper Mario Galaksi Filmi\";s:14:\"original_title\";s:28:\"The Super Mario Galaxy Movie\";s:8:\"overview\";s:536:\"Mario, Luigi ve arkadaşları, bu kez Mantar Krallığı’nın dışına çıkarak galaksiler arasında geçen bir yolculuğa katılır. Farklı gezegenlerde ilerleyen ekip, yeni karakterlerle karşılaşırken evrendeki dengeyi tehdit eden bir planla da yüzleşir. Bowser ve Bowser Jr.’ın kontrolü ele geçirme girişimi, Mario ve ekibini yıldızlar arası bir mücadeleye sürükler. Yol boyunca karşılarına çıkan engeller ve ittifaklar, bu kez çok daha büyük bir tehdide karşı birlikte hareket etmelerini gerektirir.\";s:11:\"poster_path\";s:32:\"/hoA55UeOCYnO2EkX93EFa2e6g1i.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"en\";s:9:\"genre_ids\";a:5:{i:0;i:10751;i:1;i:35;i:2;i:12;i:3;i:14;i:4;i:16;}s:10:\"popularity\";d:331.7673;s:12:\"release_date\";s:10:\"2026-04-01\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:8.166;s:10:\"vote_count\";i:2526;}i:14;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/ew3EqF9VLTxmK64OsHT7p7lr4wT.jpg\";s:2:\"id\";i:1280738;s:5:\"title\";s:8:\"Amansız\";s:14:\"original_title\";s:9:\"火遮眼\";s:8:\"overview\";s:209:\"Eski bir özel kuvvet askeri, kayıp kızını kurtarmak için kuzey Myanmar\'a sızar ve dolandırıcılık çeteleri ile organ kaçakçılarına karşı savaşarak suç patronuyla son bir hesaplaşmaya girer.\";s:11:\"poster_path\";s:32:\"/zP19YO60jwEsfKd5Qf1UvA5uJu8.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"en\";s:9:\"genre_ids\";a:2:{i:0;i:28;i:1;i:80;}s:10:\"popularity\";d:91.0011;s:12:\"release_date\";s:10:\"2026-06-10\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:8.6;s:10:\"vote_count\";i:7;}i:15;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/2D3W3Jp0VYsLhXTEfnvhbMvQEzk.jpg\";s:2:\"id\";i:1560681;s:5:\"title\";s:27:\"Kötülüğün Rengi: Siyah\";s:14:\"original_title\";s:19:\"Kolory zła: Czerń\";s:8:\"overview\";s:183:\"Sakin bir kasabada genç bir çocuk ortadan kaybolur. Kasabaya yeni atanan savcı, bu olay ile eski bir kayıp vakası arasında beklenmedik bağlantılar keşfetmeye başlayacaktır.\";s:11:\"poster_path\";s:32:\"/kqGS7zqOjMK6LsV6XjKUz5yreYZ.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"pl\";s:9:\"genre_ids\";a:3:{i:0;i:53;i:1;i:9648;i:2;i:80;}s:10:\"popularity\";d:88.5168;s:12:\"release_date\";s:10:\"2026-06-10\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:7;s:10:\"vote_count\";i:14;}i:16;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/2fgcRuaseQ9RIiTAUDbLtymnj2z.jpg\";s:2:\"id\";i:1274706;s:5:\"title\";s:15:\"İsimsiz Kadın\";s:14:\"original_title\";s:14:\"La desconocida\";s:8:\"overview\";s:173:\"Bir yük konteynerinin içinde hafızasını kaybetmiş bir kadın bulununca iki dedektif, kadının kimliğini ve onun canına kastedenleri bulmak için zamanla yarışır.\";s:11:\"poster_path\";s:32:\"/wrjKPBd4ieJMSxO7n5GothE9WAB.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"es\";s:9:\"genre_ids\";a:2:{i:0;i:53;i:1;i:80;}s:10:\"popularity\";d:68.0323;s:12:\"release_date\";s:10:\"2026-06-05\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:4.9;s:10:\"vote_count\";i:39;}i:17;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/m3Pom6pbD51bBv3syz8NMHda3fz.jpg\";s:2:\"id\";i:1368337;s:5:\"title\";s:7:\"Odyssey\";s:14:\"original_title\";s:11:\"The Odyssey\";s:8:\"overview\";s:388:\"Homeros\'un aynı adlı destanının bir uyarlamasıdır. Truva Savaşı\'ndan sonra İthaka Kralı Odysseus\'un evine dönüş yolculuğunu konu alıyor. Bu epik macerada, Odysseus\'un Polyphemus (tek gözlü dev), Sirenler ve büyücü tanrıça Circe gibi mitolojik figürlerle karşılaşmaları anlatılıyor. Film, Odysseus\'un eşi Penelope ile yeniden bir araya gelmesiyle son buluyor.\";s:11:\"poster_path\";s:32:\"/xzympITdMuHOwTvEkZsZlVGYQjo.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"en\";s:9:\"genre_ids\";a:3:{i:0;i:12;i:1;i:28;i:2;i:14;}s:10:\"popularity\";d:35.4597;s:12:\"release_date\";s:10:\"2026-07-15\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:0;s:10:\"vote_count\";i:0;}i:18;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/u53UYu5XG2hNgWGvs3xGhAVzypl.jpg\";s:2:\"id\";i:1327819;s:5:\"title\";s:11:\"Hoplayanlar\";s:14:\"original_title\";s:7:\"Hoppers\";s:8:\"overview\";s:267:\"Hayvansever Mabel, insan bilincini gerçeğe yakın robotik hayvanlara aktarmak için tasarlanmış akıllı yeni bir teknolojiyi kullanır. Bu sayede kunduzlarla iletişim kurar ve hayvanlar dünyasında hayal edebileceğinin ötesinde gizemleri açığa çıkarır.\";s:11:\"poster_path\";s:32:\"/eYjLQ3ULyr3nWj218Cu7YYU0Z8x.jpg\";s:10:\"media_type\";s:5:\"movie\";s:17:\"original_language\";s:2:\"en\";s:9:\"genre_ids\";a:5:{i:0;i:12;i:1;i:16;i:2;i:35;i:3;i:10751;i:4;i:878;}s:10:\"popularity\";d:126.9489;s:12:\"release_date\";s:10:\"2026-03-04\";s:8:\"softcore\";b:0;s:5:\"video\";b:0;s:12:\"vote_average\";d:8.184;s:10:\"vote_count\";i:1536;}i:19;a:16:{s:5:\"adult\";b:0;s:13:\"backdrop_path\";s:32:\"/g2aOpyCO1vEyUZURh3V5uaHu187.jpg\";s:2:\"id\";i:1288341;s:5:\"title\";s:13:\"Seven Snipers\";s:14:\"original_title\";s:13:\"Seven