INSERT INTO `movies` VALUES (1,1273221,'Korkunç Bir Film 6','Scary Movie','İki arkadaş kendilerini bir kez daha katillerin, canavarların ve doğaüstü yaratıkların karıştığı bir kaosun içinde bulurlar.','/9mia27aPqVkvPtFbHZphG0tXpXY.jpg','/lj6AaDqDUbzm2XJltFNHeAm2uXN.jpg','2026-06-03',95,5.7,224,153.459,'korkunc-bir-film-6','2026-06-11 08:33:15','2026-06-11 08:33:15'),(2,4247,'Korkunç Bir Film','Scary Movie','Günümüzün en popüler korku filmleriyle dalga geçen bu filmde, bir grup tanıdık görünümlü genç, kendilerini, belli belirsizden biraz daha kolay tanınabilir maskeli bir katil tarafından takip edilirken bulur. Kurbanlar ve kahkahalar artmaya başladıkça, favori korku filmlerinizden hiçbiri, bu korkunç komik parodinin jilet gibi keskin taşlamasından kaçamayacaktır.','/5zfr8OzSddfRPnjTHICRAh4H86B.jpg','/m5dA4JZsj78EBTa2D6imWOAebwB.jpg','2000-07-07',88,6.4,7829,93.480,'korkunc-bir-film','2026-06-12 03:58:41','2026-06-12 03:58:41');
